import{_ as e,o,c as r,a2 as t}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"Era de Exploração Interplanar","description":"","frontmatter":{},"headers":[],"relativePath":"pt/78-跨位面探索纪元.md","filePath":"pt/78-跨位面探索纪元.md"}'),i={name:"pt/78-跨位面探索纪元.md"};function s(n,a,d,l,c,p){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="era-de-exploracao-interplanar" tabindex="-1">Era de Exploração Interplanar <a class="header-anchor" href="#era-de-exploracao-interplanar" aria-label="Permalink to &quot;Era de Exploração Interplanar&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>78</td></tr><tr><td>Módulo</td><td>Eras Históricas e Eventos Importantes</td></tr><tr><td>Palavras-chave Principais</td><td>Exploração interplanar, grandes descobertas planares, acordo arqueológico, observação primeiro depois intervenção, simbiose interestelar</td></tr></tbody></table><h2 id="i-condicoes-de-abertura-da-era-de-exploracao-interplanar" tabindex="-1">I. Condições de Abertura da Era de Exploração Interplanar <a class="header-anchor" href="#i-condicoes-de-abertura-da-era-de-exploracao-interplanar" aria-label="Permalink to &quot;I. Condições de Abertura da Era de Exploração Interplanar&quot;">​</a></h2><p>A Era de Exploração Interplanar é uma nova era aberta após o estabelecimento da República de Todas as Raças, correspondendo à fase de transição da &quot;evolução da consciência&quot; para a &quot;simbiose interestelar&quot; no caminho de ascensão de quatro estágios. A abertura desta era requer o amadurecimento simultâneo de três condições:</p><ul><li><strong>Condição técnica</strong>: A tecnologia da lei espacial atinge o reino do &quot;espaço-fonte&quot;, tornando possível a abertura estável de canais interplanares; a tecnologia do espelho de cópia e do espaço isolado amadurece, fornecendo garantia técnica para exploração de baixa poluição</li><li><strong>Condição institucional</strong>: A República de Todas as Raças é estabelecida, e a política unificada de exploração interplanar e o acordo arqueológico são concluídos</li><li><strong>Condição de motivação</strong>: O trabalho de ascensão dos planos conhecidos avança de forma ordenada, e a civilização tem a capacidade e a vontade de se expandir para planos desconhecidos</li></ul><p>Quando essas três condições amadurecem simultaneamente, a República de Todas as Raças anuncia formalmente o lançamento do &quot;Grande Plano de Exploração&quot;, e a Era de Exploração Interplanar começa assim.</p><h2 id="ii-principios-basicos-da-exploracao-interplanar" tabindex="-1">II. Princípios Básicos da Exploração Interplanar <a class="header-anchor" href="#ii-principios-basicos-da-exploracao-interplanar" aria-label="Permalink to &quot;II. Princípios Básicos da Exploração Interplanar&quot;">​</a></h2><p>A exploração interplanar segue estritamente os seguintes princípios básicos, que estão escritos na &quot;Lei Básica da Exploração Interplanar&quot;:</p><table tabindex="0"><thead><tr><th>Princípio</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Observação primeiro, depois intervenção limitada</td><td>Para planos desconhecidos, primeiro realizar observação passiva, e só após compreensão suficiente realizar contato e intervenção limitados</td></tr><tr><td>Exploração de baixa poluição</td><td>Adotar o plano arqueológico de espelho de cópia + espaço isolado, apenas transmitir conhecimento de volta, não trazer matéria e vida para dentro ou para fora</td></tr><tr><td>Proteção da civilização nativa</td><td>Para planos com civilizações nativas, respeitar seu direito de desenvolvimento autônomo, não impor à força o sistema de simbiose</td></tr><tr><td>Compartilhamento de recursos</td><td>O conhecimento e os recursos descobertos na exploração pertencem a toda a civilização, e nenhuma organização pode monopolizar os resultados da exploração</td></tr><tr><td>Segurança em primeiro lugar</td><td>A segurança no processo de exploração é sempre colocada em primeiro lugar, e a exploração de planos de alto risco deve passar por uma avaliação de risco rigorosa</td></tr></tbody></table><h2 id="iii-meios-tecnicos-de-exploracao" tabindex="-1">III. Meios Técnicos de Exploração <a class="header-anchor" href="#iii-meios-tecnicos-de-exploracao" aria-label="Permalink to &quot;III. Meios Técnicos de Exploração&quot;">​</a></h2><p>A exploração interplanar utiliza de forma integrada várias tecnologias centrais da civilização simbiótica:</p><ol><li><strong>Tecnologia de varredura planar</strong>: Varredura planar remota baseada no módulo de percepção da lei espacial, capaz de obter informações básicas (estrutura espacial, nível de energia, sinais de vida, etc.) sem contato com o plano alvo</li><li><strong>Plano arqueológico de espelho de cópia</strong>: Realizar cópia de espelho de alta precisão do plano alvo, realizar pesquisa aprofundada na cópia de espelho no espaço isolado, e apenas transmitir o conhecimento de volta</li><li><strong>Sonda de comunicação interplanar</strong>: Dispositivo de comunicação de lei em miniatura, que pode ser enviado ao plano alvo para observação próxima, com dados transmitidos de volta em tempo real através da rede de comunicação interplanar</li><li><strong>Percepção do domínio da consciência</strong>: Cultivadores de alto nível realizam percepção remota do plano alvo através do domínio da consciência, obtendo informações no nível da consciência que a tecnologia de varredura não consegue capturar</li><li><strong>Implantação remota de âncoras</strong>: Para planos com alto nível de segurança, é possível implantar âncoras temporárias remotamente para estabelecer canais de conexão estáveis</li></ol><h2 id="iv-organizacao-e-implementacao-da-exploracao" tabindex="-1">IV. Organização e Implementação da Exploração <a class="header-anchor" href="#iv-organizacao-e-implementacao-da-exploracao" aria-label="Permalink to &quot;IV. Organização e Implementação da Exploração&quot;">​</a></h2><p>A exploração interplanar é organizada e implementada de forma unificada pela &quot;Agência de Exploração Interplanar&quot; da República de Todas as Raças, adotando o modelo de &quot;exploração hierárquica&quot;:</p><table tabindex="0"><thead><tr><th>Nível de Exploração</th><th>Tipo de Alvo</th><th>Método de Exploração</th><th>Configuração de Pessoal</th></tr></thead><tbody><tr><td>Exploração de Nível 1</td><td>Planos áridos sem vida</td><td>Varredura remota + pesquisa de espelho de cópia</td><td>Principalmente equipe técnica</td></tr><tr><td>Exploração de Nível 2</td><td>Planos com vida inferior</td><td>Arqueologia de espelho de cópia + investigação de campo limitada</td><td>Equipe técnica + biólogos</td></tr><tr><td>Exploração de Nível 3</td><td>Planos com civilização nativa</td><td>Observação primeiro, depois contato, seguindo estritamente o protocolo de contato</td><td>Equipe completa + diplomatas + observadores éticos</td></tr><tr><td>Exploração de Nível 4</td><td>Planos de alto risco / desconhecidos</td><td>Apenas pesquisa de simulação em espaço isolado, proibido contato de campo</td><td>Equipe de segurança do mais alto nível</td></tr></tbody></table><p>Cada projeto de exploração deve passar pelo processo completo de &quot;solicitação de exploração — avaliação de risco — revisão ética — aprovação e implementação — monitoramento de processo — compartilhamento de resultados&quot;.</p><h2 id="v-descobertas-importantes-da-era-de-exploracao" tabindex="-1">V. Descobertas Importantes da Era de Exploração <a class="header-anchor" href="#v-descobertas-importantes-da-era-de-exploracao" aria-label="Permalink to &quot;V. Descobertas Importantes da Era de Exploração&quot;">​</a></h2><p>Após o início da Era de Exploração Interplanar, a civilização simbiótica fez uma série de descobertas importantes:</p><ul><li><strong>Descoberta de novas raças</strong>: Descoberta de um grande número de raças inteligentes anteriormente desconhecidas em planos desconhecidos, expandindo significativamente a linhagem de todas as raças. Essas novas raças gradualmente se juntam à República de Todas as Raças após escolha voluntária</li><li><strong>Descoberta de novas leis</strong>: Existem diferenças na estrutura das leis de diferentes planos, e várias novas variantes de leis foram descobertas na exploração, enriquecendo a base teórica dos trezentos sistemas de cultivo</li><li><strong>Ruínas de civilizações antigas</strong>: Descoberta de ruínas de várias civilizações extintas da era pré-âncora, obtendo uma grande quantidade de conhecimento histórico valioso através da arqueologia de espelho de cópia</li><li><strong>Civilizações simbióticas de outros planos</strong>: Descoberta em alguns planos de civilizações nativas que desenvolveram independentemente o conceito de simbiose, formando uma ressonância de pensamento através do espaço com a civilização simbiótica de âncora</li><li><strong>Exploração dos limites do universo</strong>: A exploração gradualmente toca os limites conhecidos de Hengyuanzhou, e a compreensão da estrutura geral do universo se aprofunda continuamente</li></ul><h2 id="vi-desafios-e-reflexoes-na-exploracao" tabindex="-1">VI. Desafios e Reflexões na Exploração <a class="header-anchor" href="#vi-desafios-e-reflexoes-na-exploracao" aria-label="Permalink to &quot;VI. Desafios e Reflexões na Exploração&quot;">​</a></h2><p>A exploração interplanar não foi sempre tranquila, e o processo também encontrou desafios:</p><ul><li><strong>Conflito cultural</strong>: No contato com civilizações nativas, ocorreram mal-entendidos e conflitos culturais, o que promoveu a melhoria contínua do protocolo de contato</li><li><strong>Controvérsia ética na exploração</strong>: Houve um debate ético contínuo sobre &quot;se devemos entrar em contato ativamente com civilizações nativas&quot;, e finalmente se formou o consenso de &quot;não ser ativo, não evitar, respeitar a escolha&quot;</li><li><strong>Acidente de segurança</strong>: Ocorreu um acidente de ruptura da barreira do espaço isolado na exploração de planos de alto risco; embora não tenha causado consequências graves, promoveu uma maior melhoria dos padrões de segurança</li><li><strong>Alocação de recursos</strong>: A exploração em larga escala requer o consumo de grandes quantidades de recursos, e o equilíbrio entre o investimento em exploração e o investimento no bem-estar local tornou-se o foco do debate político</li></ul><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A Era de Exploração Interplanar é a &quot;Era das Grandes Navegações&quot; da civilização simbiótica de âncora. Ela expandiu o horizonte da civilização dos planos conhecidos para todo o universo, e ao descobrir novos mundos, também aprofundou a compreensão de si mesma. O plano de exploração de baixa poluição de espelho de cópia + espaço isolado faz com que a exploração da civilização simbiótica se diferencie de toda a expansão colonial predatória da história — o que levamos não é conquista e pilhagem, mas respeito e conhecimento; o que trazemos de volta não é recursos e escravos, mas compreensão e sabedoria. Quando os planos explorados forem suficientes e a rede de âncoras for densa o suficiente, a porta da era da simbiose interestelar se abrirá lentamente.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>77-Estabelecimento da República de Todas as Raças</li><li>79-Perspectiva da Era da Simbiose Interestelar</li><li>84-Programa Geral do Acordo Arqueológico</li></ul>',26)])])}const v=e(i,[["render",s]]);export{u as __pageData,v as default};
